package com.akshat.edithglasses\n\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\nimport org.json.JSONArray\nimport org.json.JSONObject\nimport java.io.BufferedReader\nimport java.io.InputStreamReader\nimport java.net.HttpURLConnection\nimport java.net.URL\n\nclass GrokClient {\n    suspend fun ask(question: String): Result<String> = withContext(Dispatchers.IO) {\n        val apiKey = BuildConfig.XAI_API_KEY.trim()\n        if (apiKey.isBlank() || apiKey == "PASTE_YOUR_XAI_API_KEY_HERE") {\n            return@withContext Result.failure(IllegalStateException("Grok API key is not configured"))\n        }\n\n        var connection: HttpURLConnection? = null\n        try {\n            connection = (URL("https://api.x.ai/v1/chat/completions").openConnection() as HttpURLConnection).apply {\n                requestMethod = "POST"\n                connectTimeout = 15_000\n                readTimeout = 60_000\n                doOutput = true\n                setRequestProperty("Authorization", "Bearer " + apiKey)\n                setRequestProperty("Content-Type", "application/json")\n                setRequestProperty("Accept", "application/json")\n            }\n\n            val body = JSONObject().apply {\n                put("model", "grok-4.7")\n                put("stream", false)\n                put("messages", JSONArray().apply {\n                    put(JSONObject().apply {\n                        put("role", "system")\n                        put("content", "You are JARVIS inside EDITH smart glasses. Answer clearly, accurately, and concisely. Plain text only. No markdown tables, no emojis, and no unnecessary preamble. Keep answers suitable for a small 128x64 OLED display.")\n                    })\n                    put(JSONObject().apply {\n                        put("role", "user")\n                        put("content", question)\n                    })\n                })\n            }.toString()\n\n            connection.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }\n\n            val status = connection.responseCode\n            val stream = if (status in 200..299) connection.inputStream else connection.errorStream\n            val responseText = BufferedReader(InputStreamReader(stream, Charsets.UTF_8)).use { it.readText() }\n\n            if (status !in 200..299) {\n                val message = runCatching { JSONObject(responseText).optString("error") }.getOrDefault("")\n                val suffix = if (message.isNotBlank()) ": " + message else ""\n                return@withContext Result.failure(RuntimeException("Grok request failed (" + status + ")" + suffix))\n            }\n\n            val answer = JSONObject(responseText)\n                .getJSONArray("choices")\n                .getJSONObject(0)\n                .getJSONObject("message")\n                .optString("content")\n                .trim()\n\n            if (answer.isBlank()) Result.failure(RuntimeException("Grok returned an empty answer"))\n            else Result.success(answer)\n        } catch (e: Exception) {\n            Result.failure(e)\n        } finally {\n            connection?.disconnect()\n        }\n    }\n}\n